{(next) => {
          setDeleting(next);
          // The row is stale once the org is gone; refresh so the operator is
          // not left staring at an organization that no longer exists.
          if (!next && previewError === "not_found") router.refresh();
        }}

attributes.onSelect:
{(id) => {
        // Preserve status/method/search, drop pagination: page 4 of the whole
        // org is rarely page 4 of one event, and landing on an empty page reads
        // as "this event has no payments".
        const next = new URLSearchParams(search.toString());
        if (id === ALL_EVENTS) next.delete("event");
        else next.set("event", id);
        next.delete("page");
        const qs = next.toString();
        startTransition(() => {
          router.push(qs ? `${pathname}?${qs}` : pathname, { scroll: false });
        });
      }}

